}:root {
  color-scheme: light;

  /* Pass 3 palette (DESIGN_SYSTEM.md §2.1), copied from the accepted prototype. */
  --kp-purple-100: #f6e6fe;
  --kp-purple-600: #9900cc;
  --kp-purple-700: #7900a3;
  --kp-gold-50: #fcf6e9;
  --kp-gold-100: #faebce;
  --kp-gold-500: #a87d01;
  --kp-gold-700: #684c00;
  --kp-neutral-100: #f4f1f5;
  --kp-neutral-200: #e6e2e8;
  --kp-neutral-300: #d3ced5;
  --kp-neutral-500: #848087;
  --kp-neutral-600: #656168;
  --kp-neutral-800: #2d2b2f;
  --kp-neutral-900: #161418;

  --k-bg: var(--kp-gold-50);
  --k-surface: #ffffff;
  --k-sunken: var(--kp-neutral-100);
  --k-text: var(--kp-neutral-900);
  --k-text-muted: var(--kp-neutral-600);
  --k-border: var(--kp-neutral-200);
  --k-border-strong: var(--kp-neutral-300);
  --k-field-border: var(--kp-neutral-500);
  --k-action: var(--kp-purple-600);
  --k-action-strong: var(--kp-purple-700);
  --k-on-action: #ffffff;
  --k-action-tint: var(--kp-purple-100);
  --k-focus: var(--kp-purple-600);
  --k-attn: var(--kp-gold-500);
  --k-attn-tint: var(--kp-gold-100);
  --k-attn-ink: var(--kp-gold-700);

  /* Compatibility aliases removed only when all existing components use --k-* directly. */
  --background: var(--k-bg);
  --bg: var(--k-bg);
  --surface: var(--k-surface);
  --surface-sunken: var(--k-sunken);
  --text: var(--k-text);
  --muted: var(--k-text-muted);
  --border: var(--k-border);
  --input-border: var(--k-field-border);
  --border-strong: var(--k-border-strong);
  --primary: var(--k-action);
  --primary-hover: var(--k-action-strong);
  --primary-soft: var(--k-action-tint);
  --primary-disabled: var(--kp-neutral-500);
  --error: #9c253d;
  --danger: var(--error);
  --error-soft: #fdecef;
  --danger-soft: var(--error-soft);
  --fresh: #1f7a53;
  --fresh-soft: #e6f5ee;
  --stale: #8a5a00;
  --stale-soft: #fdf3e2;
  --neutral-label: #5b5568;
  --neutral-soft: var(--k-sunken);

  --font-sans: 'Inter Variable', Inter, system-ui, -apple-system, 'Segoe UI', Arial, sans-serif;

  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-7: 1.75rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;

  --radius-sm: 0.5rem;
  --radius: 0.75rem;
  --radius-lg: 1rem;
  --radius-xl: 1.25rem;
  --radius-full: 999px;
  --border-width: 1px;

  --shadow-card: 0 1px 2px rgba(37, 29, 51, 0.06);
  --shadow-sticky: 0 -2px 12px rgba(37, 29, 51, 0.08);
  --shadow-pop: 0 8px 24px rgba(37, 29, 51, 0.12);
  --k-elev-3: 0 -8px 28px rgba(22, 20, 24, 0.16);
  --k-elev-frame: 0 2px 4px rgba(22, 20, 24, 0.06), 0 14px 34px rgba(22, 20, 24, 0.10);

  --dur-fast: 120ms;
  --dur: 160ms;
  --dur-slow: 240ms;
  --ease: cubic-bezier(0.2, 0, 0.2, 1);

  --z-base: 0;
  --z-sticky: 10;
  --z-overlay: 20;
  --z-toast: 30;
}

* { box-sizing: border-box; }

html { scrollbar-gutter: stable both-edges; }

body {
  margin: 0;
  background: var(--background);
  color: var(--text);
  font-family: var(--font-sans);
  font-size: 1rem;
  line-height: 1.5;
}

input, button { font: inherit; }
button, input, a { -webkit-tap-highlight-color: transparent; }
button { cursor: pointer; }
a { color: inherit; }
h1, h2, p, dl, dd { margin: 0; }
:focus-visible { outline: 3px solid var(--primary); outline-offset: 4px; }

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; transition: none !important; }
}
/* Ported verbatim from the accepted mockup (docs/product/mockup/seller-ai-first-rev1/kaida.css), scoped to .kaida;
   icons are the mockup's own files under /kaida/icons. Do not restyle here: change the mockup first. */
/* KAIDA · AI-first seller concept — shared styles. Tokens = KAIDA design system (light theme). */
.kaida{
  --bg:#faf8fb;--surface:#ffffff;--raised:#ffffff;--sunken:#f4f1f6;--line:#e8e4eb;--line-control:#8b858e;
  --ink:#19161b;--ink2:#615b64;--ink3:#6e6871;
  --primary:#9900cc;--primary-hover:#7a06a3;--primary-pressed:#5b0a7a;--on-primary:#ffffff;--primary-text:#9900cc;--primary-soft:#f8e5ff;--focus:#9900cc;
  --sun:#fec92f;--on-sun:#100d11;
  --success:#007b2a;--success-soft:#eefbf0;--warning:#9c5a00;--warning-soft:#fff5e9;--danger:#c2272d;--danger-soft:#fff1ef;--info:#006ebf;--info-soft:#edf8ff;
  --scrim:#19161b8f;
  --shadow-md:0 4px 12px #5b0a7a1a,0 2px 4px #19161b0f;--shadow-lg:0 12px 32px #5b0a7a24,0 4px 8px #19161b14;
  --sans:Roboto,Geologica,system-ui,-apple-system,"Segoe UI",sans-serif;--display:Geologica,Roboto,system-ui,sans-serif;
}
.kaida, .kaida *{box-sizing:border-box}
.kaida{margin:0;font-family:var(--sans);color:var(--ink);background:#e9e5ec;-webkit-font-smoothing:antialiased}
.kaida button, .kaida input, .kaida textarea, .kaida select{font:inherit;color:inherit}
.kaida a{color:var(--primary-text)}
.kaida a:hover{color:var(--primary-hover)}
/* ---------- phone ---------- */
.kaida .ph{width:360px;height:760px;background:var(--bg);border-radius:28px;border:1px solid #d7d2da;overflow:hidden;position:relative;display:flex;flex-direction:column;box-shadow:0 1px 2px #19161b14}
.kaida .ph.tall{height:1180px}
.kaida .bar{height:56px;flex:none;display:flex;align-items:center;gap:4px;padding:0 4px 0 4px;background:var(--surface);border-bottom:1px solid var(--line)}
.kaida .bar.flat{background:var(--bg);border-bottom:0}
.kaida .bar-t{flex:1;min-width:0;font:600 17px/24px var(--display);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;padding-left:8px}
.kaida .bar-t.c{text-align:center;padding-left:0}
.kaida .body{flex:1;min-height:0;overflow:hidden;padding:16px;display:flex;flex-direction:column;gap:16px}
.kaida .body.np{padding:0}
.kaida .foot{flex:none;padding:12px 16px 16px;background:var(--surface);border-top:1px solid var(--line);display:flex;flex-direction:column;gap:8px}
.kaida .foot.bare{background:transparent;border-top:0}
.kaida .sp{flex:1}
.kaida .body>*, .kaida .sheet>*, .kaida .foot>*, .kaida .wbody>*{flex-shrink:0}
/* bottom nav */
.kaida .nav{height:64px;flex:none;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));background:var(--surface);border-top:1px solid var(--line)}
.kaida .nav>a, .kaida .nav>span, .kaida .nav>button{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;font:500 12px/16px var(--sans);color:var(--ink2);text-decoration:none;position:relative}
.kaida .nav .on{color:var(--primary-text)}
.kaida .nav .on::before{content:"";position:absolute;top:0;left:30%;right:30%;height:3px;border-radius:0 0 3px 3px;background:var(--primary)}
.kaida .dot{position:absolute;top:10px;margin-left:22px;min-width:16px;height:16px;border-radius:8px;background:var(--danger);color:#fff;font:600 10px/16px var(--sans);text-align:center;padding:0 4px}
/* type */
.kaida .ov{font:500 12px/16px var(--sans);letter-spacing:.06em;text-transform:uppercase;color:var(--ink3)}
.kaida .h1{margin:0;font:700 26px/32px var(--display);letter-spacing:-.015em;text-wrap:balance}
.kaida .h2{margin:0;font:600 21px/28px var(--display);letter-spacing:-.01em;text-wrap:balance}
.kaida .h3{margin:0;font:600 17px/24px var(--display)}
.kaida .t{margin:0;font:400 15px/22px var(--sans)}
.kaida .tl{margin:0;font:400 17px/24px var(--sans)}
.kaida .ts{margin:0;font:500 15px/22px var(--sans)}
.kaida .c{margin:0;font:400 13px/18px var(--sans);color:var(--ink3)}
.kaida .c2{color:var(--ink2)}
.kaida .lbl{font:500 14px/20px var(--sans)}
.kaida .pr{font:700 18px/22px var(--display);font-variant-numeric:tabular-nums}
.kaida .pr-lg{font:700 26px/30px var(--display);font-variant-numeric:tabular-nums;letter-spacing:-.01em}
.kaida .num{font-variant-numeric:tabular-nums}
.kaida .clamp2{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.kaida .pt{color:var(--primary-text)}
.kaida .dn{color:var(--danger)}
.kaida .ok{color:var(--success)}
/* buttons */
.kaida .btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;height:44px;padding:0 16px;border-radius:14px;border:0;font:500 14px/20px var(--sans);letter-spacing:.005em;text-decoration:none;cursor:pointer;white-space:nowrap}
.kaida .btn-p{background:var(--primary);color:var(--on-primary)}
.kaida .btn-p.lg{height:auto;min-height:52px;font-size:15px;white-space:normal;text-align:center;padding:8px 16px}
.kaida .btn-o{background:var(--surface);color:var(--ink);border:1.5px solid var(--line-control)}
.kaida .btn-g{background:transparent;color:var(--primary-text);padding:0 12px}
.kaida .btn-d{background:var(--danger);color:#fff}
.kaida .btn-do{background:var(--surface);color:var(--danger);border:1.5px solid var(--danger)}
.kaida .btn.w{width:100%;white-space:normal;text-align:center;height:auto;min-height:44px}
.kaida .btn.sm{height:36px;padding:0 12px;border-radius:10px}
.kaida .btn[disabled], .kaida .btn.dis{background:var(--sunken);color:var(--ink3);border-color:transparent;cursor:not-allowed}
.kaida .btn.pressed{background:var(--primary-pressed)}
.kaida .btn.focus{outline:2px solid var(--focus);outline-offset:2px}
.kaida .ib{width:48px;height:48px;flex:none;display:inline-flex;align-items:center;justify-content:center;border:0;background:transparent;border-radius:24px;color:var(--ink);cursor:pointer;padding:0}
.kaida .spin{width:18px;height:18px;border-radius:50%;border:2.5px solid currentColor;border-right-color:transparent;display:inline-block;flex:none}
/* icons (mask) */
.kaida .ic{display:inline-block;width:24px;height:24px;flex:none;background-color:currentColor;-webkit-mask-image:var(--m);mask-image:var(--m);-webkit-mask-size:contain;mask-size:contain;-webkit-mask-repeat:no-repeat;mask-repeat:no-repeat;-webkit-mask-position:center;mask-position:center}
.kaida .ic.sm{width:20px;height:20px}
.kaida .ic.xs{width:16px;height:16px}
.kaida .ic.lg{width:32px;height:32px}
